using System;using System.IO;using System.Linq;using System.Threading;using SplifyWin;
class CsqttDnsLive20261023 {
 static int Main(string[] args){try{string link=Console.ReadLine();var node=Links.Read(link).Single();link=null;if(node.Protocol!="csqtt"||CsqttGenerations.For(node).Id!="2.5")throw new InvalidDataException("Expected reusable CSQTT 2.5 test profile");var core=new NetworkCore(new StateStore(args[0]));RuntimeResources.Prepare(args[0]);foreach(var id in new[]{"csqtt25","csqtt-bridge"}){var p=core.Engines.Package(id);string archive=Path.Combine(args[1],id=="csqtt25"?"mcrf-csqtt25-windows-amd64-vkturn-options-20261022-1.zip":"mcrf-csqtt-bridge-windows-amd64.zip");string stage=Path.Combine(core.Engines.StorageRoot,".download-live-"+id);Directory.CreateDirectory(stage);core.Engines.InstallArchive(p,archive,stage,CancellationToken.None);}Console.WriteLine("LIVE isolated CSQTT2.5 transport; no TUN, system DNS or routes changed");foreach(string url in new[]{"https://www.youtube.com/generate_204","https://gamebanana.com/games/20948"})using(var timeout=new CancellationTokenSource(85000)){Console.WriteLine("LIVE checking "+new Uri(url).Host);try{core.ProbeIsolatedAsync(node,url,timeout.Token).GetAwaiter().GetResult();Console.WriteLine("LIVE HTTPS PASS "+new Uri(url).Host);}catch(Exception ex){Console.WriteLine("LIVE FAIL "+ex.GetType().Name+": "+JournalStyle.Redact(ex.Message));return 2;}}Console.WriteLine("LIVE RESULT PASS");return 0;}catch(Exception ex){Console.WriteLine("LIVE setup failed "+ex.GetType().Name);return 1;}}
}
